package com.integrydt.backend.controller;

import com.fasterxml.jackson.databind.*;import com.integrydt.backend.security.AuthenticatedUser;import com.integrydt.backend.service.AuditService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@RestController @RequestMapping("/api/v1/jobs")
public class JobsController {
 private final JdbcTemplate db;private final ObjectMapper json;private final AuditService audit;public JobsController(JdbcTemplate db,ObjectMapper json,AuditService audit){this.db=db;this.json=json;this.audit=audit;}
 public record CreateJobRequest(String deviceId,String toolCode,String action,JsonNode parameters){} public record SystemInfoRequest(String deviceId){}
 @PostMapping @PreAuthorize("hasAuthority('PERM_tools.execute')") @Transactional public ResponseEntity<?> create(@RequestBody CreateJobRequest r,Authentication auth,HttpServletRequest req){AuthenticatedUser u=(AuthenticatedUser)auth.getPrincipal();if(blank(r.deviceId())||blank(r.toolCode())||blank(r.action()))return ResponseEntity.badRequest().body(Map.of("error","invalid_job_request"));if("sftp-files".equals(r.toolCode())&&"delete".equals(r.action())&&!u.permissions().contains("roles.manage"))return ResponseEntity.status(403).build();Integer dc=db.queryForObject("SELECT COUNT(*) FROM devices WHERE id=? AND company_id=? AND status<>'revoked'",Integer.class,r.deviceId(),u.companyId());if(dc==null||dc==0)return ResponseEntity.status(404).body(Map.of("error","device_not_found"));var defs=db.queryForList("SELECT CAST(t.id AS CHAR) toolId,CAST(g.id AS CHAR) gadgetId,CAST(gv.id AS CHAR) gadgetVersionId,g.code gadgetCode,gv.version FROM company_tools ct JOIN tools t ON t.id=ct.tool_id AND t.enabled=1 JOIN gadgets g ON g.id=t.gadget_id AND g.enabled=1 JOIN company_gadget_policies cgp ON cgp.company_id=ct.company_id AND cgp.gadget_id=g.id AND cgp.enabled=1 JOIN gadget_versions gv ON gv.gadget_id=g.id AND gv.status='published' WHERE ct.company_id=? AND ct.enabled=1 AND t.code=? AND gv.id=(SELECT gv2.id FROM gadget_versions gv2 WHERE gv2.gadget_id=g.id AND gv2.status='published' ORDER BY gv2.published_at DESC,gv2.created_at DESC LIMIT 1) LIMIT 1",u.companyId(),r.toolCode());if(defs.isEmpty())return ResponseEntity.status(404).body(Map.of("error","tool_not_available"));var norm=normalize(u.companyId(),r);if(norm.error()!=null)return ResponseEntity.badRequest().body(Map.of("error",norm.error()));var d=defs.get(0);String id=UUID.randomUUID().toString();String payload=norm.value()==null?null:toJson(norm.value());db.update("INSERT INTO jobs(id,company_id,requested_by_user_id,device_id,tool_id,gadget_id,gadget_version_id,action,payload_json,status) VALUES(?,?,?,?,?,?,?,?,CASE WHEN ? IS NULL THEN NULL ELSE CAST(? AS JSON) END,'queued')",id,u.companyId(),u.id(),r.deviceId(),d.get("toolId"),d.get("gadgetId"),d.get("gadgetVersionId"),r.action(),payload,payload);db.update("INSERT INTO job_events(job_id,event_type,message) VALUES(?,'queued',?)",id,r.toolCode()+"/"+r.action()+" queued");audit.write(u.companyId(),u.id(),"tools.execute","job",id,"queued","web-api",req.getRemoteAddr(),Map.of("deviceId",r.deviceId(),"toolCode",r.toolCode(),"action",r.action()));return ResponseEntity.accepted().body(Map.of("id",id,"status","queued","gadget",d.get("gadgetCode"),"version",d.get("version")));}
 @PostMapping("/system-info") @PreAuthorize("hasAuthority('PERM_tools.execute')") public ResponseEntity<?> systemInfo(@RequestBody SystemInfoRequest r,Authentication a,HttpServletRequest q){return create(new CreateJobRequest(r.deviceId(),"system-info","system-info",null),a,q);}
 @PostMapping("/{id}/cancel") @PreAuthorize("hasAuthority('PERM_tools.execute')") @Transactional public ResponseEntity<?> cancel(@PathVariable String id,Authentication auth,HttpServletRequest req){AuthenticatedUser u=(AuthenticatedUser)auth.getPrincipal();var rows=db.queryForList("SELECT status FROM jobs WHERE id=? AND company_id=?",id,u.companyId());if(rows.isEmpty())return ResponseEntity.notFound().build();String status=(String)rows.get(0).get("status");if("queued".equals(status)){db.update("UPDATE jobs SET status='cancelled',finished_at=CURRENT_TIMESTAMP(6) WHERE id=? AND company_id=? AND status='queued'",id,u.companyId());db.update("INSERT INTO job_events(job_id,event_type,message) VALUES(?,'cancelled','Job cancelled before dispatch')",id);audit.write(u.companyId(),u.id(),"jobs.cancel","job",id,"cancelled","web-api",req.getRemoteAddr(),null);return ResponseEntity.ok(Map.of("id",id,"status","cancelled"));}if(Set.of("dispatched","downloading_gadget","running").contains(status)){Integer n=db.queryForObject("SELECT COUNT(*) FROM job_events WHERE job_id=? AND event_type='cancel_requested'",Integer.class,id);if(n!=null&&n==0)db.update("INSERT INTO job_events(job_id,event_type,message) VALUES(?,'cancel_requested','Cancellation requested by user')",id);audit.write(u.companyId(),u.id(),"jobs.cancel","job",id,"requested","web-api",req.getRemoteAddr(),null);return ResponseEntity.accepted().body(Map.of("id",id,"status","cancel_requested"));}return ResponseEntity.status(409).body(Map.of("error","job_not_cancellable","status",status));}
 @GetMapping("/{id}") @PreAuthorize("hasAuthority('PERM_jobs.read')") public ResponseEntity<?> get(@PathVariable String id,Authentication a){String c=((AuthenticatedUser)a.getPrincipal()).companyId();var r=db.queryForList("SELECT CAST(j.id AS CHAR) id,j.action,j.status,j.created_at createdAt,j.dispatched_at dispatchedAt,j.started_at startedAt,j.finished_at finishedAt,d.name deviceName,t.code toolCode,g.code gadgetCode,gv.version,r.exit_code exitCode,r.stdout_text stdout,r.stderr_text stderr,CAST(r.result_json AS CHAR) resultJson FROM jobs j JOIN devices d ON d.id=j.device_id JOIN tools t ON t.id=j.tool_id JOIN gadgets g ON g.id=j.gadget_id JOIN gadget_versions gv ON gv.id=j.gadget_version_id LEFT JOIN job_results r ON r.job_id=j.id WHERE j.id=? AND j.company_id=?",id,c);return r.isEmpty()?ResponseEntity.notFound().build():ResponseEntity.ok(r.get(0));}
 @GetMapping("/{id}/events") @PreAuthorize("hasAuthority('PERM_jobs.read')") public ResponseEntity<?> events(@PathVariable String id,Authentication a){String c=((AuthenticatedUser)a.getPrincipal()).companyId();Integer n=db.queryForObject("SELECT COUNT(*) FROM jobs WHERE id=? AND company_id=?",Integer.class,id,c);if(n==null||n==0)return ResponseEntity.notFound().build();return ResponseEntity.ok(db.queryForList("SELECT event_type type,message,CAST(metadata_json AS CHAR) metadata,created_at createdAt FROM job_events WHERE job_id=? ORDER BY id",id));}
 private Normalized normalize(String company,CreateJobRequest r){JsonNode p=r.parameters();try{switch(r.toolCode()){case"repository-manager"->{if(!Set.of("status","branch","fetch","pull").contains(r.action()))return new Normalized(null,"repository_action_not_allowed");String id=text(p,"profileId");if(id==null)return new Normalized(null,"profile_id_required");var x=db.queryForList("SELECT local_path localPath FROM repository_profiles WHERE id=? AND company_id=?",id,company);return x.isEmpty()?new Normalized(null,"repository_profile_not_found"):new Normalized(Map.of("path",x.get(0).get("localPath")),null);}case"sftp-files"->{if(!Set.of("list","mkdir","download","upload","rename","delete").contains(r.action()))return new Normalized(null,"sftp_action_not_allowed");String id=text(p,"profileId");if(id==null)return new Normalized(null,"profile_id_required");var x=db.queryForList("SELECT host,port,username,remote_path remotePath,identity_file_path identityFilePath FROM sftp_profiles WHERE id=? AND company_id=?",id,company);if(x.isEmpty())return new Normalized(null,"sftp_profile_not_found");var q=x.get(0);Map<String,Object> m=new LinkedHashMap<>();m.put("host",q.get("host"));m.put("port",q.get("port"));m.put("username",q.get("username"));m.put("remotePath",Optional.ofNullable(text(p,"remotePath")).orElse((String)q.get("remotePath")));m.put("identityFilePath",q.get("identityFilePath"));m.put("localPath",text(p,"localPath"));m.put("newRemotePath",text(p,"newRemotePath"));m.put("confirm",bool(p,"confirm"));return new Normalized(m,null);}case"script-runner"->{if(!"run-approved".equals(r.action()))return new Normalized(null,"script_action_not_allowed");String id=text(p,"scriptId");if(id==null)return new Normalized(null,"script_id_required");var x=db.queryForList("SELECT script_body scriptBody,sha256,timeout_seconds timeoutSeconds FROM script_catalog WHERE id=? AND company_id=? AND enabled=1",id,company);if(x.isEmpty())return new Normalized(null,"script_not_found");return new Normalized(x.get(0),null);}case"screen-recorder"->{if(!"record-screen".equals(r.action()))return new Normalized(null,"recording_action_not_allowed");int d=num(p,"durationSeconds",5),f=num(p,"fps",1);if(d<1||d>15||f<1||f>2)return new Normalized(null,"invalid_recording_settings");return new Normalized(Map.of("durationSeconds",d,"fps",f),null);}case"input-automation"->{if(!"run-sequence".equals(r.action()))return new Normalized(null,"automation_action_not_allowed");String id=text(p,"sequenceId");if(id==null)return new Normalized(null,"sequence_id_required");var x=db.queryForList("SELECT CAST(steps_json AS CHAR) steps FROM automation_sequences WHERE id=? AND company_id=? AND enabled=1",id,company);if(x.isEmpty())return new Normalized(null,"sequence_not_found");return new Normalized(Map.of("steps",json.readTree((String)x.get(0).get("steps"))),null);}default->{return new Normalized(p,null);}}}catch(Exception e){return new Normalized(null,"invalid_parameters");}}
 private record Normalized(Object value,String error){} private static String text(JsonNode p,String n){return p!=null&&p.isObject()&&p.hasNonNull(n)&&p.get(n).isTextual()&&!p.get(n).asText().isBlank()?p.get(n).asText():null;}private static int num(JsonNode p,String n,int d){return p!=null&&p.has(n)&&p.get(n).canConvertToInt()?p.get(n).asInt():d;}private static boolean bool(JsonNode p,String n){return p!=null&&p.has(n)&&p.get(n).isBoolean()&&p.get(n).asBoolean();}private static boolean blank(String s){return s==null||s.isBlank();}private String toJson(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
}
